import{_ as a,o as i,c as s,ag as d}from"./chunks/framework.C9sp7nFj.js";const c=JSON.parse('{"title":"WaitSimDI 等待虚拟数字量输入","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/4. IO 指令/WaitSimDI.md","filePath":"3. 指令/4. IO 指令/WaitSimDI.md","lastUpdated":1778862643000}'),e={name:"3. 指令/4. IO 指令/WaitSimDI.md"};function r(n,t,o,h,l,p){return i(),s("div",null,[...t[0]||(t[0]=[d('<h1 id="waitsimdi-等待虚拟数字量输入" tabindex="-1">WaitSimDI 等待虚拟数字量输入 <a class="header-anchor" href="#waitsimdi-等待虚拟数字量输入" aria-label="Permalink to &quot;WaitSimDI 等待虚拟数字量输入&quot;">​</a></h1><p>虚拟数字量输入等待指令用于在设定的时长内，监控指定的**虚拟数字量输入（SimDI）**端口值。当该虚拟端口的状态与目标值匹配时，程序继续执行。该指令常用于等待后台程序（通过 <code>RUN</code> 启动的程序）发送的逻辑信号或复杂的内部状态变更。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p><code>WaitSimDI (SIMDIN, VALUE, T, INTERENABLE, RET, [Goto])</code></p><p>WaitSimDI(虚拟数字输入端口, 目标十进制值, 超时时间, 中断使能, 超时判断值, [跳转标签])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>SIMDIN</td><td>SimDI</td><td>需要监控的目标虚拟数字量输入端口</td><td>必填</td></tr><tr><td>VALUE</td><td>int 或 INT 变量</td><td>期望等待的状态值（0 或 1）</td><td>必填</td></tr><tr><td>T</td><td>int 或 INT 变量</td><td>等待限时，单位 ms（0：强制等待直到信号满足）</td><td>必填</td></tr><tr><td>INTERENABLE</td><td>int</td><td>程序暂停恢复后的计时逻辑（0：继续计时，1：重新计时）</td><td>必填</td></tr><tr><td>RET</td><td>INT 变量</td><td>记录指令执行结束后的状态（0：成功，1：超时）</td><td>必填</td></tr><tr><td>[Goto]</td><td>label</td><td>超时后程序指针跳转到的指定标签名</td><td>可选</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WaitSimDI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (SimDI1, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, INT1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>逻辑描述：</strong></p><p>程序将等待虚拟数字量输入变量 <strong>SimDI1</strong> 变为 <strong>1</strong> 的状态，设定最长等待时间为 <strong>1000ms</strong>。如果在此期间程序暂停并恢复，系统将在暂停前的基础上<strong>继续计时</strong>。若 1000ms 时间耗尽仍未等到该信号，则将变量 <strong>INT1</strong> 置为 <strong>1</strong> 以标记超时，随后程序继续执行下一条指令。</p>',15)])])}const k=a(e,[["render",r]]);export{c as __pageData,k as default};
